28	// tryPushRef attempts to push a custom ref using an explicit refspec.
29	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
30		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
31		defer cancel()
32	
33		refSpec := fmt.Sprintf("%s:%s", refName, refName)
34		result, err := remote.Push(ctx, target, refSpec)
35		outputStr := result.Output
36		if err != nil {
37			return classifyPushFailure(ctx, outputStr, err)
38		}
39	
40		return nil
41	}
42	
43	type v2RefPushResult struct {
44		refName plumbing.ReferenceName
45		result  pushResult
46		err     error
47	}
48	
49	type pendingV2FullGenerationPublicationResult struct {
50		successfulRefs          []plumbing.ReferenceName
51		fullCurrentResetHandled bool
52	}
53	
54	func tryPushV2Refs(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
55		if len(refs) == 0 {
56			return nil
57		}
58	
59		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
60		defer cancel()
61	
62		result, err := remote.PushWithOptions(ctx, remote.PushOptions{
63			Remote:   target,
64			RefSpecs: refSpecsForRefs(refs),
65		})
66		return parsePushRefResults(ctx, result.Output, refs, err)
67	}
68	
69	func pushV2RefsWithRecovery(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
70		resultsByRef := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
71		var retryRefs []plumbing.ReferenceName
72	
73		for _, result := range tryPushV2Refs(ctx, target, refs) {
74			if result.err == nil {
75				resultsByRef[result.refName] = result
76				continue
77			}
78			if !errors.Is(result.err, errNonFastForward) {
79				resultsByRef[result.refName] = result
80				continue
81			}
82	
83			shortRef := shortRefName(result.refName)
84			if err := fetchAndMergeRef(ctx, target, result.refName); err != nil {
85				resultsByRef[result.refName] = v2RefPushResult{
86					refName: result.refName,
87					err:     fmt.Errorf("couldn't sync %s: %w", shortRef, err),
88				}
89				continue
90			}
91			retryRefs = append(retryRefs, result.refName)
92		}
93	
94		if len(retryRefs) > 0 {
95			for _, result := range tryPushV2Refs(ctx, target, retryRefs) {
96				if result.err != nil {
97					result.err = fmt.Errorf("failed to push %s after sync: %w", shortRefName(result.refName), result.err)
98				}
99				resultsByRef[result.refName] = result
100			}
101		}
102	
103		results := make([]v2RefPushResult, 0, len(refs))
104		for _, refName := range refs {
105			result, ok := resultsByRef[refName]
106			if !ok {
107				result = v2RefPushResult{
108					refName: refName,
109					err:     errors.New("push result missing"),
110				}
111			}
112			results = append(results, result)
113		}
114		return results
115	}
116	
117	func publishPendingV2FullGenerationPublications(
118		ctx context.Context,
119		repo *git.Repository,
120		store *checkpoint.V2GitStore,
121		target string,
122		publications []checkpoint.PendingV2FullGenerationPublication,
123	) (pendingV2FullGenerationPublicationResult, error) {
124		var result pendingV2FullGenerationPublicationResult
125		if len(publications) == 0 {
126			return result, nil
127		}
128	
129		currentRefName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
130		var localCurrentRef *plumbing.Reference
131		for {
132			latestResetPublicationIndex := latestPendingFullCurrentResetPublicationIndex(publications)
133			if latestResetPublicationIndex == -1 {
134				break
135			}
136			var err error
137			localCurrentRef, err = repo.Reference(currentRefName, true)
138			if err != nil {
139				return result, fmt.Errorf("read local %s: %w", shortRefName(currentRefName), err)
140			}
141			latestResetPublication := publications[latestResetPublicationIndex]
142			if pendingResetPublicationMatchesLocalCurrent(ctx, repo, latestResetPublication, localCurrentRef.Hash()) {
143				break
144			}
145			if err := store.RemovePendingFullGenerationPublications(ctx, []checkpoint.PendingV2FullGenerationPublication{latestResetPublication}); err != nil {
146				return result, fmt.Errorf("clear stale pending v2 full generation publications: %w", err)
147			}
148			publications = slices.Delete(publications, latestResetPublicationIndex, latestResetPublicationIndex+1)
149		}
150	
151		archiveRefs := pendingFullArchiveRefs(publications)
152		if len(archiveRefs) > 0 {
