558	func fetchRelatedRemoteRotationArchive(ctx context.Context, fetchTarget string, archives []string, localCurrentHash plumbing.Hash) (fetchedRemoteRotationArchive, error) {
559		refSpecs := make([]string, 0, len(archives))
560		archiveTmpRefs := make([]plumbing.ReferenceName, 0, len(archives))
561	
562		for _, archive := range archives {
