// fetch fails during capability negotiation. Detect that specific error
// and transparently retry with a full fetch — same shape as the
// pre-optimization behavior, no settings change required for legacy
// servers. Other fetch errors (network, auth, ref missing) propagate.
probeBlobless := true
if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
	Remote:    fetchTarget,
	RefSpecs:  refSpecs,
